import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    if n % 2 == 0:
        print("Even")
    else:
        print("Odd")

if __name__ == '__main__':
    solve()

class Solution:
    def isEvenOrOdd(self, n: int) -> str:
        if n % 2 == 0:
            return "Even"
        return "Odd"

